*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:var(--sp11-ink);font-family:var(--sp11-sans);font-size:15px}.sp11-page{overflow:hidden}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.sp11-container{width:min(1640px,calc(100% - 56px));margin-inline:auto}.sp11-section{padding:86px 0}.sp11-topbar{background:#f4f1eb;padding:11px 0;font-family:var(--sp11-serif)}.sp11-topbar .sp11-container{display:flex;align-items:center;justify-content:space-between}.sp11-topbar .sp11-container>div{display:flex;gap:28px}.sp11-topbar a{font-family:var(--sp11-sans)}.sp11-header{background:#fff}.sp11-header-row{min-height:112px;display:flex;align-items:center;gap:28px}.sp11-logo{display:flex;align-items:center;gap:10px;min-width:260px}.sp11-logo-mark{width:64px;height:70px;border:4px solid var(--sp11-teal);border-radius:54% 46% 48% 52%;display:grid;place-items:center;position:relative;color:var(--sp11-teal);font-family:var(--sp11-serif);font-size:38px}.sp11-logo-mark i{position:absolute;right:-8px;top:-8px;font-size:22px}.sp11-logo>span:last-child{display:flex;flex-direction:column}.sp11-logo strong{font:700 31px/1 var(--sp11-serif);color:var(--sp11-teal)}.sp11-logo em{color:var(--sp11-peach);font-style:normal}.sp11-logo small{font-size:8px;letter-spacing:2.2px;margin-top:7px}.sp11-nav{display:flex;align-items:center;gap:26px;flex:1;justify-content:center;white-space:nowrap}.sp11-nav a{padding:42px 0 10px;border-bottom:2px solid transparent;font-family:var(--sp11-serif);font-size:16px}.sp11-nav a:hover,.sp11-nav a.is-active{color:var(--sp11-teal);border-color:var(--sp11-teal)}.sp11-actions{display:flex;align-items:center;gap:13px}.sp11-actions>button,.sp11-actions>a:not(.sp11-hotline):not(.sp11-book){width:38px;height:38px;border:0;background:transparent;display:grid;place-items:center;font-size:22px;position:relative}.sp11-actions b{position:absolute;right:-2px;top:-4px;font:600 10px var(--sp11-sans);background:var(--